using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MobileNoticeTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private async Task<(string User,Guid Property,Guid Member,Guid Public,Guid Management,Guid Message)> Setup(){var user=Guid.NewGuid().ToString();var p=new Property("Notice fixture","City","District","Address");var m=new PropertyMembership(p.Id,user);var person=new Person(p.Id,"Fixture","Recipient");var a=new Announcement(p.Id,"Public fixture","Content",ContentAudience.ALL_MEMBERS);a.Publish(DateTimeOffset.UtcNow);var management=new Announcement(p.Id,"Management fixture","Content",ContentAudience.MANAGEMENT);management.Publish(DateTimeOffset.UtcNow);var draft=new Announcement(p.Id,"Hidden draft","Content",ContentAudience.ALL_MEMBERS);var archived=new Announcement(p.Id,"Hidden archived","Content",ContentAudience.ALL_MEMBERS);archived.Publish(DateTimeOffset.UtcNow);archived.Archive();var msg=new PersonMessage(p.Id,person.Id,Guid.NewGuid(),new string('a',64),user,"Own message","Private content");var foreign=new PersonMessage(p.Id,person.Id,Guid.NewGuid(),new string('b',64),"foreign","Foreign message","Hidden content");await factory.WithDb(async db=>{db.AddRange(p,m,person,a,management,draft,archived,msg,foreign);await db.SaveChangesAsync();});return(user,p.Id,m.Id,a.Id,management.Id,msg.Id);}
 private static string Path(Guid p,string role="MANAGER",string kind="ANNOUNCEMENT",int page=1,Guid? item=null)=>$"/api/v1/mobile/notices?propertyId={p}&role={role}&kind={kind}&page={page}"+(item.HasValue?$"&itemId={item}":"");
 [PostgresFact]public async Task PublishedAudienceAndPersonalMessageProjectionAreScoped(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var feed=(await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property)))!;Assert.Equal(2,feed.Total);Assert.Equal(2,feed.Unread);Assert.False(feed.PushAvailable);Assert.DoesNotContain(feed.Items,x=>x.Title.StartsWith("Hidden"));var json=await c.GetStringAsync(Path(s.Property,kind:"MESSAGE"));Assert.DoesNotContain("personId",json);Assert.DoesNotContain("recipientUserId",json);Assert.DoesNotContain("Foreign message",json);Assert.Single((await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property,kind:"MESSAGE")))!.Items);using var accountant=TestToken.Client(factory,s.User,"ACCOUNTANT");var limited=(await accountant.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property,"ACCOUNTANT")))!;Assert.Equal(s.Public,Assert.Single(limited.Items).Id);Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync(Path(s.Property,"ACCOUNTANT",item:s.Management))).StatusCode);}
 [PostgresFact]public async Task ConcurrentReadIsIdempotentAndVisibleToAnotherDevice(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var cmd=new MobileNoticeReadCommand(s.Property,null,"MANAGER","ANNOUNCEMENT",s.Public);var results=await Task.WhenAll(c.PostAsJsonAsync("/api/v1/mobile/notices/read",cmd),c.PostAsJsonAsync("/api/v1/mobile/notices/read",cmd));Assert.All(results,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));var reads=await Task.WhenAll(results.Select(r=>r.Content.ReadFromJsonAsync<MobileNoticeReadResult>()));Assert.Equal(reads[0]!.ReadAt,reads[1]!.ReadAt);using var device=TestToken.Client(factory,s.User,"MANAGER");var feed=(await device.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property)))!;Assert.Equal(1,feed.Unread);Assert.NotNull(feed.Items.Single(x=>x.Id==s.Public).ReadAt);await factory.WithDb(async db=>Assert.Equal(1,await db.Set<MobileAnnouncementRead>().CountAsync(x=>x.OwnerUserId==s.User)));}
 [PostgresFact]public async Task MessageReadUpdatesExistingCenterReadState(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var cmd=new MobileNoticeReadCommand(s.Property,null,"MANAGER","MESSAGE",s.Message);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/v1/mobile/notices/read",cmd)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/v1/mobile/notices/read",cmd)).StatusCode);Assert.Equal(0,(await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property,kind:"MESSAGE")))!.Unread);await factory.WithDb(async db=>Assert.NotNull((await db.PersonMessages.FindAsync(s.Message))!.ReadAt));}
 [PostgresFact]public async Task RoleSpoofForeignPropertyAnonymousAndRevocationFailClosed(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");using var stranger=TestToken.Client(factory,"stranger","MANAGER");using var anon=TestToken.Client(factory,null,"");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Path(s.Property))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await stranger.GetAsync(Path(s.Property))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,"SUPER_ADMIN"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(Guid.NewGuid()))).StatusCode);await factory.WithDb(async db=>{(await db.PropertyMemberships.FindAsync(s.Member))!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/v1/mobile/notices/read",new MobileNoticeReadCommand(s.Property,null,"MANAGER","ANNOUNCEMENT",s.Public))).StatusCode);}
 [PostgresFact]public async Task PreferenceIsPerAccountVersionedAndLostResponseReplaySafe(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var cmd=new MobileNoticePreferenceCommand(s.Property,null,"MANAGER",false,0);var first=(await(await c.PostAsJsonAsync("/api/v1/mobile/notices/preference",cmd)).Content.ReadFromJsonAsync<MobileNoticePreferenceDto>())!;Assert.False(first.HighlightsEnabled);Assert.Equal(1,first.Version);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/v1/mobile/notices/preference",cmd)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync("/api/v1/mobile/notices/preference",cmd with{HighlightsEnabled=true})).StatusCode);var feed=(await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property)))!;Assert.False(feed.Preference.HighlightsEnabled);Assert.Equal(2,feed.Unread);var other=await Setup();using var device=TestToken.Client(factory,other.User,"MANAGER");Assert.True((await device.GetFromJsonAsync<MobileNoticeSnapshot>(Path(other.Property)))!.Preference.HighlightsEnabled);}
 [PostgresFact]public async Task FeedPagingAndInvalidQueriesAreBounded(){var s=await Setup();await factory.WithDb(async db=>{for(var i=0;i<49;i++){var a=new Announcement(s.Property,"Fixture "+i,"Content",ContentAudience.ALL_MEMBERS);a.Publish(DateTimeOffset.UtcNow);db.Add(a);}await db.SaveChangesAsync();});using var c=TestToken.Client(factory,s.User,"MANAGER");var first=(await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property)))!;var second=(await c.GetFromJsonAsync<MobileNoticeSnapshot>(Path(s.Property,page:2)))!;Assert.Equal(51,first.Total);Assert.Equal(50,first.Items.Length);Assert.Single(second.Items);Assert.Equal(51,second.Unread);Assert.Empty(first.Items.Select(x=>x.Id).Intersect(second.Items.Select(x=>x.Id)));Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(s.Property,page:0))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(s.Property,kind:"INVALID"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,item:Guid.NewGuid()))).StatusCode);}
 [PostgresFact]public async Task ResidentUnitContextMustMatchRealActiveOccupancy(){var s=await Setup();Guid unit=Guid.Empty,occupancy=Guid.Empty;await factory.WithDb(async db=>{var p=(await db.Properties.FindAsync(s.Property))!;var b=p.AddBuilding("A");var u=b.AddUnit("1",1,90m);unit=u.Id;var person=new Person(s.Property,"Tenant","Fixture","5550000000","fixture@example.test");person.SetProfile("NATURAL","FOREIGN","US","FIXTURE123",null,null,null,s.User);var link=new UnitOccupancy(s.Property,u.Id,person.Id,OccupancyType.TENANT,DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-1));occupancy=link.Id;db.AddRange(b,u,person,link);await db.SaveChangesAsync();});using var c=TestToken.Client(factory,s.User,"RESIDENT");var path=Path(s.Property,"TENANT")+$"&unitId={unit}";var feed=(await c.GetFromJsonAsync<MobileNoticeSnapshot>(path))!;Assert.Equal(s.Public,Assert.Single(feed.Items).Id);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,"TENANT")+$"&unitId={Guid.NewGuid()}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,"MANAGER"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,"TENANT",item:s.Management)+$"&unitId={unit}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/v1/mobile/notices/read",new MobileNoticeReadCommand(s.Property,unit,"TENANT","ANNOUNCEMENT",s.Public))).StatusCode);await factory.WithDb(async db=>{(await db.UnitOccupancies.FindAsync(occupancy))!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(path)).StatusCode);}
 [PostgresFact]public async Task DisabledPreferenceCannotBeReadAsDefaultOrOverwritten(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");await c.PostAsJsonAsync("/api/v1/mobile/notices/preference",new MobileNoticePreferenceCommand(s.Property,null,"MANAGER",false,0));await factory.WithDb(async db=>{var p=await db.Set<MobileNoticePreference>().SingleAsync(x=>x.OwnerUserId==s.User);p.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/v1/mobile/notices/preference",new MobileNoticePreferenceCommand(s.Property,null,"MANAGER",true,2))).StatusCode);}

}
